namespace BlazorNotifications.Services;

public class NotificationItem
{
    public int Id { get; set; }
    public string Message { get; set; } = string.Empty;
    public DateTime Timestamp { get; set; }
}

public class NotificationService
{
    private int _nextId = 1;
    private readonly Lock _lock = new();

    private readonly List<NotificationItem> _notifications = new();

    public NotificationService()
    {
        // Seed initial fake data
        Add("Welcome to the app!");
        Add("Your profile was updated.");
        Add("New feature available: dark mode.");
    }

    public List<NotificationItem> GetAll()
    {
        lock (_lock)
        {
            return _notifications.ToList();
        }
    }

    public List<NotificationItem> GetSince(int lastId)
    {
        lock (_lock)
        {
            return _notifications.Where(n => n.Id > lastId).ToList();
        }
    }

    /// <summary>Simulates an external system pushing notifications over time.</summary>
    public void SimulateIncoming()
    {
        var messages = new[]
        {
            "Server deployment completed.",
            "You have a new follower.",
            "Disk usage above 80%.",
            "Backup finished successfully.",
            "New comment on your post.",
            "Payment received.",
        };

        var msg = messages[Random.Shared.Next(messages.Length)];
        Add(msg);
    }

    private void Add(string message)
    {
        lock (_lock)
        {
            _notifications.Add(new NotificationItem
            {
                Id = _nextId++,
                Message = message,
                Timestamp = DateTime.UtcNow
            });
        }
    }
}

